clc; clearvars;
%%
root_dir = "..";
addpath(genpath(fullfile(root_dir,"O3_Lidar/proc_functions/")))
addpath(genpath(fullfile(root_dir,"signal_analysis/functions/")))

data_path = fullfile(root_dir,"O3_processed_data/");

dataFiles = dir(fullfile(data_path, "*.mat"));
fileNames = string({dataFiles.name});

fid = 1;
prof_id = 1;

min_alt = 700;
max_alt = 30e3;

data = load(fullfile(data_path,fileNames(fid)));
%%
t = data.times_avg;
z = data.z_vec';

alt_id = z >= min_alt & z <= max_alt;

z = z(alt_id);
zkm = z.*1e-3;
on = fillmissing(data.mg_on_fr(alt_id,:),"constant",0);
on_bg = fillmissing(data.pc_on_fr_bg(alt_id,:),"constant",0); % not sure if its valid to use pc background with merged signal

off = fillmissing(data.mg_off_fr(alt_id,:),"constant",0);
off_bg = fillmissing(data.pc_off_fr_bg(alt_id,:),"constant",0);

qO3 = data.q_o3_mg_merged(alt_id,:);
NO3 = fillmissing(data.N_o3_mg_merged(alt_id,:), "constant",0);
Na = data.Na(alt_id,:);
Ta = data.Ta(alt_id,:);
sigma_o3_on = data.sigma_o3_on(alt_id,:);
sigma_o3_off = data.sigma_o3_off(alt_id,:);

n_prof = size(on,2);
%%
%[text] Produce synthetic profile here
% Ozone Absorption Cross Section
BDM = load("..\signal_analysis\cross_sections\ozone\bdm\bdm_287_299.mat");

% Ozone profile
N_O3 = NO3;

% Air number density
Nair = Na(:,prof_id);

% On and off wavelengths
lam_on = 287.2e-9;
lam_off = 299.1e-9;

% Ozone absorption cross section
% sigma_o3_on = sigma_o3_on;
% sigma_o3_off = sigma_o3_off;

% Emitted pulse power at each wavelength
% E0_on = 10.6e-3;
% E0_off = 6.3e-3;
E0_on = 50e-3;
E0_off = 50e-3;

% Efficiency factor at each wavelength
eta_on = 1;
eta_off = 1;

% Detector quantum efficiency
etaQ = 0.7;

% Telescope primary area
t_r = .2;   % Radius of the receiver in meters
o_r = 0.1;  % Radius of the obstruction
A = pi.*(t_r^2 - o_r^2);

% DAQ sampling rate
f = 40e6;
tau = 1/f; % Laser pulse duration

% Overlap function
O = ones(size(z));
%%
x0 = [1 0 0];

rate2count = tau .*1e6;
count2rate = 1 ./ rate2count;

x_on = NaN(length(x0),n_prof);
x_off = NaN(length(x0),n_prof);

on_sim_fit = NaN(size(on));
off_sim_fit = NaN(size(off));
for i=1:n_prof
    on_tmp = (on(:,i) + on_bg(:,i)) .* rate2count;
    off_tmp = (off(:,i) + off_bg(:,i)) .* rate2count;

    N_O3_tmp = N_O3(:,i);

    fun_on =  @(x0,z1) signal(z1,lam_on, E0_on, A,tau,x0(1), etaQ,Nair,sigma_o3_on(:,i), N_O3_tmp,O) + z.*x0(2) + x0(3); % make separate array to hold signal result and background result
    fun_off = @(x0,z1) signal(z1,lam_off,E0_off,A,tau,x0(1), etaQ,Nair,sigma_o3_off(:,i),N_O3_tmp,O) + z.*x0(2) + x0(3);

    opt=optimoptions("lsqcurvefit","Display","off");

    x_on(:,i) =  lsqcurvefit(fun_on, x0,z,on_tmp, [0 0 0],[],opt);
    x_off(:,i) = lsqcurvefit(fun_off,x0,z,off_tmp,[0 0 0],[],opt);
    on_sim_fit(:,i) = fun_on(x_on(:,i),z);
    off_sim_fit(:,i) = fun_off(x_off(:,i),z);
end

navg = 12000;
[on_sim_fit,on_sim_fit_nsy] = add_noise(on_sim_fit,0,navg);
[off_sim_fit,off_sim_fit_nsy] = add_noise(off_sim_fit,0,navg);

on_sim_fit = on_sim_fit .* count2rate;
off_sim_fit = off_sim_fit .* count2rate;
%%
on_plt = on(:,prof_id) + on_bg(:,prof_id);
off_plt = off(:,prof_id) + off_bg(:,prof_id);

y_lim = [1e0 1e5];

on_off = [on_plt off_plt];
on_off_dispname = ["On" "Off"];
prof_plot(zkm,on_off,[],y_lim,"Altitude (km)","Count Rate (MHz)","Real Lidar Signals",on_off_dispname) %[output:2651432a]
on_off_sim_dispname = ["On" "Off"];
on_off_sim_fit = [on_sim_fit(:,prof_id) off_sim_fit(:,prof_id)];
prof_plot(zkm,on_off_sim_fit,[],y_lim,"Altitude (km)","Count Rate (MHz)","Simulated and Fitted Lidar Signals",on_off_sim_dispname) %[output:80aeded5]
figure; %[output:7c529e42]
scatter(on_off, on_off_sim_fit) %[output:7c529e42]
title("Real v Sim") %[output:7c529e42]
xlabel("Real Data") %[output:7c529e42]
ylabel("Simulated Data") %[output:7c529e42]
prof_plot(zkm,N_O3(:,i)) %[output:5ccd4703]
%%
figure; %[output:03647951] %[output:9b2c19c7]
yyaxis left %[output:9b2c19c7]
plot(x_on(1,:)) %[output:9b2c19c7]
hold on  %[output:9b2c19c7]
plot(x_off(1,:)) %[output:9b2c19c7]
hold off %[output:9b2c19c7]
xlabel("Profile Index") %[output:9b2c19c7]
ylabel("Efficiency Factor") %[output:9b2c19c7]
legend("On","Off","Location","best") %[output:9b2c19c7]
grid on %[output:9b2c19c7]
yyaxis right %[output:9b2c19c7]
plot(x_on(2,:)) %[output:9b2c19c7]
hold on %[output:9b2c19c7]
plot(x_off(2,:)) %[output:9b2c19c7]
hold off %[output:9b2c19c7]
ylabel("Transmittance Factor") %[output:9b2c19c7]
legend("Efficiency Factor On","Efficiency Factor Off","Transmittance Factor On","Transmittance Factor Off","Location","best") %[output:9b2c19c7]
% use same color scale
im_plot(t,zkm,on,[],[],"","","MHz","On Signal Real",12); %[output:8a92bc10]
im_plot(t,zkm,off,[],[],"","","MHz","Off Signal Real",12); %[output:1b16925a]
im_plot(t,zkm,on_sim_fit,[],[],"","","MHz","On Signal Simulated",12); %[output:34a50a81]
im_plot(t,zkm,off_sim_fit,[],[],"","","MHz","Off Signal Simulated",12); %[output:7955d4da]
ND_plot(t,zkm,qO3) %[output:90285a49] %[output:937280d2]
%%
function im_plot(x,y,z,c_lim,y_lim,x_label,y_label,c_label,title_str,fs)
    figure;
    I = imagesc(x, y, z);
    cbar_tolnet=colorbar_tolnet_func;
    colormap(cbar_tolnet);
    ax = gca;

    set(gca, 'ColorScale', 'log')

    if ~isempty(c_lim)
        ax.CLim = c_lim;
    end

    set(gca,'YDir','normal');
    set(I,'AlphaData',~isnan(z));

    if ~isempty(y_lim)
        ylim(y_lim)
    end
    c = colorbar;
    c.Label.String = c_label;
    xlabel(x_label)
    ylabel(y_label)
    title(title_str)
    fontsize(fs,"points")
end

function prof_plot(x,y,x_lim,y_lim,x_label,y_label,title_str,disp_name)
    arguments
        x 
        y 
        x_lim       = []
        y_lim       = []
        x_label     = []
        y_label     = []
        title_str   = []
        disp_name   = []
    end

    n_prof = size(y,2);

    figure;
    hold on
    for i=1:n_prof
        if ~isempty(disp_name)
            plot(x,y(:,i),'DisplayName',disp_name(i))
            legend 
        else
            plot(x,y(:,i))
        end
    end
    hold off

    yscale log
    grid on

    if ~isempty(x_lim)
        xlim(x_lim)
    end

    if ~isempty(y_lim)
        ylim(y_lim)
    end

    if ~isempty(x_label)
        xlabel(x_label)
    end

    if ~isempty(y_label)
        ylabel(y_label)
    end

    if ~isempty(title_str)
        title(title_str)
    end
end

